# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 12)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_spans([Span(65, 125)], 10),
            ["01:10-02:10 (1h 0m)"],
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
